<script setup lang="ts">
import {onMounted,ref} from 'vue'
import {api,newKey} from '../api'
import {useRequestScope} from '../platform/request-scope'
type Cohort={id:string;label:string;usernames:string[]}
const capture=useRequestScope(),config=ref<{version:number;cohorts:Cohort[];excludedUsernames:string[]}>(),report=ref<any>(),chosen=ref(''),error=ref(''),busy=ref(false)
function names(value:string){return value.split(/[\s,，]+/).map(s=>s.trim()).filter(Boolean)}
async function load(){const scope=capture();try{const value=await api<typeof config.value>('/experience/beta/config');if(scope.valid()){config.value=value;chosen.value=value?.cohorts[0]?.id||'';await refresh()}}catch(e){if(scope.valid())error.value=(e as Error).message}}
async function refresh(){const scope=capture(),id=chosen.value;try{const value=await api('/experience/beta/report?cohort='+encodeURIComponent(id));if(scope.valid()&&chosen.value===id)report.value=value}catch(e){if(scope.valid())error.value=(e as Error).message}}
async function save(){if(!config.value)return;const scope=capture();busy.value=true;error.value='';try{const value=await api<typeof config.value>('/experience/beta/config',{method:'PUT',key:newKey(),body:{expectedVersion:config.value.version,cohorts:config.value.cohorts,excludedUsernames:config.value.excludedUsernames}});if(scope.valid()){config.value=value;await refresh()}}catch(e){if(scope.valid())error.value=(e as Error).message}finally{if(scope.valid())busy.value=false}}
const duration=(n:number|null)=>n===null?'暂无样本':(n/1000).toFixed(1)+' 秒'
onMounted(load)
</script>
<template><section class="workspace-card"><h2>内测批次与等待情况</h2><p>按已注册的用户名明确分组。管理员自动排除；验收账号请加入排除名单。分组不会改变账号权限、模型预算或出图次数。</p><p v-if="error" role="alert" class="error">{{error}}</p><template v-if="config"><fieldset :disabled="busy"><article v-for="c in config.cohorts" :key="c.id"><label>批次标识<input v-model="c.id" pattern="[a-z0-9-]+" maxlength="40"></label><label>批次名称<input v-model="c.label" maxlength="80"></label><label>测试者用户名<textarea :value="c.usernames.join('\n')" @change="c.usernames=names(($event.target as HTMLTextAreaElement).value)" rows="3"></textarea></label><button @click="config.cohorts=config.cohorts.filter(x=>x!==c)">移除这批分组</button></article><button :disabled="config.cohorts.length>=20" @click="config.cohorts.push({id:'beta-'+Date.now(),label:'新内测批次',usernames:[]})">添加内测批次</button><label>排除的验收用户名<textarea :value="config.excludedUsernames.join('\n')" @change="config.excludedUsernames=names(($event.target as HTMLTextAreaElement).value)" rows="3"></textarea></label><button @click="save">保存分组</button></fieldset><label>查看批次<select v-model="chosen" @change="refresh"><option value="">请选择已保存的批次</option><option v-for="c in config.cohorts" :key="c.id" :value="c.id">{{c.label}}</option></select></label><button @click="refresh">刷新统计</button></template><template v-if="report"><p>{{report.cohort||'未选择批次'}} · {{report.members}} 人 · 最近 {{report.days}} 天 {{report.tasks}} 个任务。当前排队 {{report.queued}}，全局生成并行上限 {{report.globalCapacity}}。</p><p>{{report.basis}}</p><p v-if="report.truncated" role="status">此批次超过统计上限，当前只展示最近 5000 个任务。</p><div class="table-scroll"><table><thead><tr><th>耗时</th><th>样本</th><th>中位数</th><th>P95</th></tr></thead><tbody><tr v-for="(label,key) in {beforeFirstCall:'调用前等待',firstText:'收到首字',total:'任务完成'}" :key="key"><td>{{label}}</td><td>{{report.timings[key].samples}}</td><td>{{duration(report.timings[key].medianMs)}}</td><td>{{duration(report.timings[key].p95Ms)}}</td></tr></tbody></table></div><p v-for="(count,code) in report.errors" :key="code">{{code}}：{{count}} 次</p><details><summary>批次事实与任务状态</summary><pre>{{JSON.stringify({factsUniqueUsers:report.factsUniqueUsers,taskStates:report.taskStates},null,2)}}</pre></details></template></section></template>
<style scoped>label{display:grid;gap:.4rem;margin:.7rem 0}article{padding:1rem 0;border-bottom:1px solid var(--line)}textarea,input,select{max-width:100%;box-sizing:border-box}.table-scroll{max-width:100%;overflow:auto}table{width:100%;text-align:left}th,td{padding:.6rem}pre{white-space:pre-wrap;overflow-wrap:anywhere}</style>
